insert into passages (id, text, difficulty_level, b, active) values
('4656848e-4fcb-49a5-b307-cbef8607b513', 'Every summer, Anna and her family go camping in the mountains. They pack a big tent, sleeping bags, and enough food for a week. Anna''s favorite part of camping is sitting by the campfire at night and looking at the stars. During the day, the family goes hiking on trails near the lake and sometimes they see deer and rabbits. Anna''s little brother likes to catch fish with their father, though he has never caught one yet. In the evening, they cook dinner over the fire and tell funny stories. Anna says camping is her favorite time of the whole year.', 1, -2.0, true),
('d06c5c10-2e14-42ed-9cb6-60313834f174', 'Every Saturday morning, Sara helps her mother at the family bakery. She wakes up early and puts on her apron before opening the shop. Customers come in to buy fresh bread, cookies, and cakes. Sara likes to arrange the cookies in the glass case because they look pretty. Her favorite job is decorating birthday cakes with colorful icing. At noon, Sara and her mother eat lunch together in the small kitchen behind the shop. By evening, most of the bread is sold, and Sara helps clean the tables and sweep the floor before they go home.', 1, -2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('1229cbe7-897b-44b8-973b-70bccfb4e513', 'sentence_completion', 'The children were very ___ when they saw the puppies playing.', NULL, '[{"id": "a", "text": "happy"}, {"id": "b", "text": "bored"}, {"id": "c", "text": "tired"}, {"id": "d", "text": "angry"}]'::jsonb, 0, '{"strategy": "saw puppies playing = ראו כלבלבים משחקים. מה מרגישים ילדים במצב כזה?", "correct_reason": "happy = שמחים. כלבלבים משחקים גורמים לשמחה.", "options_analysis": ["נכון! happy = שמחים — תגובה טבעית לכלבלבים משחקים", "bored = משועממים — הפוך מהתרגשות", "tired = עייפים — לא קשור", "angry = כועסים — לא הגיוני"]}', 1.42, -2.0, 0.25, 1, 'ai', NULL, true),
('bed4701a-3cd0-48cb-b202-e7f30fdb9439', 'sentence_completion', 'She is a very ___ girl who always helps her classmates.', NULL, '[{"id": "d", "text": "rude"}, {"id": "a", "text": "kind"}, {"id": "c", "text": "quiet"}, {"id": "b", "text": "lazy"}]'::jsonb, 1, '{"strategy": "always helps her classmates = תמיד עוזרת. איזו תכונה מתאימה למי שעוזר?", "correct_reason": "kind = טובת לב. עזרה לאחרים מעידה על טוב לב.", "options_analysis": ["rude = גסת רוח — הפוך מעזרה לאחרים", "נכון! kind = טובת לב — מתאים למי שעוזר לאחרים", "quiet = שקטה — לא קשור לעזרה", "lazy = עצלנית — עצלן לא עוזר תמיד"]}', 1.24, -2.0, 0.25, 1, 'ai', NULL, true),
('f47534fb-9b7c-4c98-b175-23069d1d2d3f', 'sentence_completion', 'The soldier was ___ when he ran into the burning building to save the child.', NULL, '[{"id": "c", "text": "lazy"}, {"id": "a", "text": "tired"}, {"id": "b", "text": "brave"}, {"id": "d", "text": "scared"}]'::jsonb, 2, '{"strategy": "ran into a burning building to save a child = רץ לבניין בוער כדי להציל ילד. איזו תכונה נדרשת?", "correct_reason": "brave = אמיץ. חילוץ מבניין בוער דורש אומץ.", "options_analysis": ["lazy = עצלן — הפוך מפעולת חילוץ", "tired = עייף — לא רלוונטי", "נכון! brave = אמיץ — נדרש כדי לרוץ לבניין בוער", "scared = מפוחד — לא בהכרח שולל אומץ אך brave מתאים יותר"]}', 1.4, -2.0, 0.25, 1, 'ai', NULL, true),
('5a7f2793-6ff7-4b5c-8ba0-42f165f17f32', 'sentence_completion', 'He always tells the truth, so everyone knows he is very ___.', NULL, '[{"id": "c", "text": "shy"}, {"id": "d", "text": "rude"}, {"id": "b", "text": "lazy"}, {"id": "a", "text": "honest"}]'::jsonb, 3, '{"strategy": "always tells the truth = תמיד אומר אמת. איזו תכונה מתאימה?", "correct_reason": "honest = כן/ישר. אמירת אמת תמיד מעידה על יושר.", "options_analysis": ["shy = ביישן — לא קשור", "rude = גס רוח — לא קשור", "lazy = עצלן — לא קשור לאמירת אמת", "נכון! honest = כן — תכונה שמתאימה למי שתמיד אומר אמת"]}', 1.42, -2.0, 0.25, 1, 'ai', NULL, true),
('cd6fa38f-e0e4-41f0-9b97-a2ded5975df9', 'sentence_completion', 'The old man was ___ and gave food to everyone who was hungry.', NULL, '[{"id": "a", "text": "generous"}, {"id": "d", "text": "angry"}, {"id": "c", "text": "tired"}, {"id": "b", "text": "selfish"}]'::jsonb, 0, '{"strategy": "gave food to everyone who was hungry = נתן אוכל לכל מי שהיה רעב. איזו תכונה זו?", "correct_reason": "generous = נדיב. חלוקת אוכל לזרים היא נדיבות.", "options_analysis": ["נכון! generous = נדיב — מתאים למי שנותן אוכל לזרים", "angry = כועס — לא קשור לנתינה", "tired = עייף — לא קשור", "selfish = אנוכי — הפוך מנתינה"]}', 1.35, -2.0, 0.25, 1, 'ai', NULL, true),
('97d4a010-c2c5-4d3f-b131-e76f0b3fcb4c', 'sentence_completion', 'The nurse spoke in a ___ voice to calm the crying baby.', NULL, '[{"id": "a", "text": "loud"}, {"id": "d", "text": "gentle"}, {"id": "c", "text": "angry"}, {"id": "b", "text": "rough"}]'::jsonb, 1, '{"strategy": "to calm the crying baby = כדי להרגיע תינוק בוכה. איזה קול מרגיע?", "correct_reason": "gentle = עדין. קול עדין מרגיע תינוק.", "options_analysis": ["loud = רם — קול רם לא מרגיע תינוק", "נכון! gentle = עדין — מרגיע תינוק בוכה", "angry = כועס — לא מרגיע", "rough = גס — לא מתאים להרגעה"]}', 1.33, -2.0, 0.25, 1, 'ai', NULL, true),
('120c6cb8-b194-406d-8a30-a7765922431b', 'sentence_completion', 'My grandmother is very ___ and waits patiently for the bus every day.', NULL, '[{"id": "c", "text": "angry"}, {"id": "b", "text": "loud"}, {"id": "a", "text": "patient"}, {"id": "d", "text": "impatient"}]'::jsonb, 2, '{"strategy": "waits patiently = מחכה בסבלנות. איזו תכונה מתאימה?", "correct_reason": "patient = סבלנית. המתנה רגועה מעידה על סבלנות.", "options_analysis": ["angry = כועסת — לא מתאים להמתנה רגועה", "loud = רועשת — לא קשור", "נכון! patient = סבלנית — מתאים למי שמחכה בשקט", "impatient = חסרת סבלנות — הפוך מ''patiently''"]}', 1.37, -2.0, 0.25, 1, 'ai', NULL, true),
('b962a8b6-f3bf-4d52-b596-64be232d8181', 'sentence_completion', 'The little boy was ___ about everything and always asked many questions.', NULL, '[{"id": "d", "text": "angry"}, {"id": "c", "text": "bored"}, {"id": "b", "text": "tired"}, {"id": "a", "text": "curious"}]'::jsonb, 3, '{"strategy": "always asked many questions = תמיד שאל הרבה שאלות. איזו תכונה זו?", "correct_reason": "curious = סקרן. שאלות רבות מעידות על סקרנות.", "options_analysis": ["angry = כועס — לא קשור לשאלות", "bored = משועמם — הפוך מסקרנות", "tired = עייף — לא קשור", "נכון! curious = סקרן — מתאים למי ששואל הרבה"]}', 1.31, -2.0, 0.25, 1, 'ai', NULL, true),
('a4190f2d-8d0b-4414-b4e2-780a8cc1e032', 'sentence_completion', 'Everyone liked him because he was always ___ to strangers.', NULL, '[{"id": "c", "text": "polite"}, {"id": "a", "text": "rude"}, {"id": "d", "text": "angry"}, {"id": "b", "text": "silent"}]'::jsonb, 0, '{"strategy": "always ___ to strangers, everyone liked him = כולם אהבו אותו כי הוא היה כזה כלפי זרים. מה גורם לאהדה?", "correct_reason": "polite = מנומס. נימוס כלפי זרים גורם לאהדה.", "options_analysis": ["נכון! polite = מנומס — גורם לאהדת אחרים", "rude = גס — הפוך מאהדה", "angry = כועס — הפוך מאהדה", "silent = שותק — לא בהכרח גורם לאהדה"]}', 1.48, -2.0, 0.25, 1, 'ai', NULL, true),
('9c348c4b-c108-4821-82b7-d7eec58cab7b', 'sentence_completion', 'The kitchen was ___ after she finished cooking dinner.', NULL, '[{"id": "b", "text": "clean"}, {"id": "a", "text": "messy"}, {"id": "c", "text": "empty"}, {"id": "d", "text": "quiet"}]'::jsonb, 1, '{"strategy": "after cooking = אחרי בישול. איך נראית מטבח אחרי בישול?", "correct_reason": "messy = מבולגן. בישול משאיר לרוב בלגן.", "options_analysis": ["clean = נקייה — לא סביר מיד אחרי בישול", "נכון! messy = מבולגן — תוצאה טבעית של בישול", "empty = ריקה — לא קשור לבישול", "quiet = שקטה — לא מתאר מראה מטבח"]}', 1.3, -2.0, 0.25, 1, 'ai', NULL, true),
('414c03b0-0619-463d-80f8-31e7692789ac', 'sentence_completion', 'He runs very ___ and always wins the school races.', NULL, '[{"id": "d", "text": "badly"}, {"id": "a", "text": "quietly"}, {"id": "c", "text": "fast"}, {"id": "b", "text": "slow"}]'::jsonb, 2, '{"strategy": "always wins the races = תמיד מנצח במרוצים. איך הוא רץ?", "correct_reason": "fast = מהר. ניצחון במירוץ דורש ריצה מהירה.", "options_analysis": ["badly = גרוע — הפוך מניצחון", "quietly = בשקט — לא רלוונטי לריצה", "נכון! fast = מהר — מסביר את הניצחונות", "slow = לאט — הפוך מניצחון במרוץ"]}', 1.21, -2.0, 0.25, 1, 'ai', NULL, true),
('4259a574-35d7-4df5-ae2f-643a7028f1d5', 'sentence_completion', 'The bridge was too ___ for large trucks to cross safely.', NULL, '[{"id": "b", "text": "wide"}, {"id": "d", "text": "short"}, {"id": "a", "text": "tall"}, {"id": "c", "text": "narrow"}]'::jsonb, 3, '{"strategy": "too ___ for large trucks = מדי בשביל משאיות גדולות. מה מונע מעבר משאיות?", "correct_reason": "narrow = צר. גשר צר מדי לא מתאים למשאיות גדולות.", "options_analysis": ["wide = רחב — הפוך, רוחב לא מונע מעבר", "short = קצר — אורך לא מונע מעבר משאית", "tall = גבוה — גובה גשר לא רלוונטי כאן", "נכון! narrow = צר — מסביר למה משאיות לא יכולות לעבור"]}', 1.38, -2.0, 0.25, 1, 'ai', NULL, true),
('ac0e46fa-24ab-4da1-89d9-7739add26cac', 'restatement', 'The cat sleeps on the sofa every afternoon.', NULL, '[{"id": "a", "text": "Every afternoon, the cat sleeps on the sofa."}, {"id": "d", "text": "The cat sleeps on the sofa only at night."}, {"id": "c", "text": "The cat never sleeps on the sofa."}, {"id": "b", "text": "The sofa sleeps on the cat every afternoon."}]'::jsonb, 0, '{"strategy": "every afternoon = כל אחר צהריים. הרגל קבוע.", "correct_reason": "אותה עובדה בדיוק, בסדר מילים הפוך.", "options_analysis": ["נכון! אותה עובדה בדיוק, סדר מילים הפוך", "''בלילה'' סותר ''every afternoon''", "''אף פעם לא'' סותר ''every afternoon''", "משפט הפוך וחסר הגיון"]}', 1.48, -2.0, 0.25, 1, 'ai', NULL, true),
('aa5ee9c5-012e-428d-8d86-e47fa4ee5a72', 'restatement', 'He was hungry, so he made a sandwich.', NULL, '[{"id": "d", "text": "He was not hungry, so he made a sandwich."}, {"id": "c", "text": "He made a sandwich because he was hungry."}, {"id": "b", "text": "He made a sandwich before he was hungry."}, {"id": "a", "text": "He was hungry, so he threw away his sandwich."}]'::jsonb, 1, '{"strategy": "hungry, so made = רעב, לכן הכין. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר ''he was hungry''", "נכון! אותה סיבה-תוצאה בדיוק", "הופך את סדר הזמן", "סותר ''made a sandwich''"]}', 1.27, -2.0, 0.25, 1, 'ai', NULL, true),
('a6f5e8db-e857-4f4e-ae30-114a981c34d8', 'restatement', 'The children play soccer after school.', NULL, '[{"id": "c", "text": "The children play soccer before school."}, {"id": "b", "text": "The children never play soccer."}, {"id": "a", "text": "After school, the children play soccer."}, {"id": "d", "text": "The children play soccer during school."}]'::jsonb, 2, '{"strategy": "after school = אחרי בית הספר. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["''לפני'' סותר ''after''", "''אף פעם לא'' סותר את המקור", "נכון! אותה עובדה בדיוק", "''במהלך'' סותר ''after school''"]}', 1.34, -2.0, 0.25, 1, 'ai', NULL, true),
('b1694d5c-54c8-4c1e-84a1-707a924785ba', 'restatement', 'She is younger than her brother.', NULL, '[{"id": "a", "text": "She and her brother are the same age."}, {"id": "b", "text": "Her brother is younger than she is."}, {"id": "c", "text": "She is older than her brother."}, {"id": "d", "text": "Her brother is older than she is."}]'::jsonb, 3, '{"strategy": "יחס גילאים הפוך: היא צעירה ממנו = הוא מבוגר ממנה.", "correct_reason": "אותו יחס בדיוק, הפוך כיוון.", "options_analysis": ["סותר את ההשוואה במקור", "הפוך תפקידים — במקור הוא מבוגר יותר", "סותר לגמרי את המקור", "נכון! אותו יחס בדיוק, הפוך כיוון"]}', 1.47, -2.0, 0.25, 1, 'ai', NULL, true),
('eb9bc5d5-4582-4111-82dc-f96a95e1bc7b', 'restatement', 'The store sells fresh fruit and vegetables.', NULL, '[{"id": "a", "text": "Fresh fruit and vegetables are sold at the store."}, {"id": "c", "text": "The store buys fresh fruit and vegetables."}, {"id": "d", "text": "The store does not sell any food."}, {"id": "b", "text": "The store sells only vegetables."}]'::jsonb, 0, '{"strategy": "sells = מוכרת. פעיל לסביל.", "correct_reason": "אותה עובדה בדיוק, בקול סביל.", "options_analysis": ["נכון! אותה עובדה בדיוק, בקול סביל", "''קונה'' הפוך ל''sells''", "סותר לגמרי — החנות כן מוכרת אוכל", "חלקי בלבד — יש גם פירות"]}', 1.41, -2.0, 0.25, 1, 'ai', NULL, true),
('243e2a79-d289-4edd-9663-cf73c684deb5', 'restatement', 'He was tired, but he still finished his homework.', NULL, '[{"id": "b", "text": "He did not finish his homework because he was tired."}, {"id": "c", "text": "Although he was tired, he finished his homework."}, {"id": "d", "text": "He was not tired, so he finished his homework."}, {"id": "a", "text": "He finished his homework before he got tired."}]'::jsonb, 1, '{"strategy": "tired, but still finished = עייף, אך בכל זאת סיים. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''still finished'' — הוא כן סיים", "נכון! אותה משמעות בדיוק: סיים למרות העייפות", "סותר ''he was tired'' במקור", "הופך את סדר האירועים"]}', 1.25, -2.0, 0.25, 1, 'ai', NULL, true),
('ebcacc65-508a-432b-a37a-5309c483eece', 'restatement', 'The teacher gave the students a difficult test.', NULL, '[{"id": "a", "text": "The teacher gave the students an easy test."}, {"id": "d", "text": "The students gave the teacher a difficult test."}, {"id": "c", "text": "The students were given a difficult test by the teacher."}, {"id": "b", "text": "The teacher did not give any test."}]'::jsonb, 2, '{"strategy": "gave...a test = נתנה מבחן. פעיל לסביל.", "correct_reason": "אותה עובדה בדיוק, בקול סביל.", "options_analysis": ["''קל'' סותר ''difficult''", "הופך את הכיוון — התלמידים לא נתנו למורה", "נכון! אותה עובדה בדיוק, בקול סביל", "סותר לגמרי — היה מבחן"]}', 1.27, -2.0, 0.25, 1, 'ai', NULL, true),
('126af6ac-cf8c-4da0-9fac-91741695d0a4', 'restatement', 'It began to rain, so they went inside.', NULL, '[{"id": "c", "text": "They stayed outside despite the rain."}, {"id": "b", "text": "They went outside because it began to rain."}, {"id": "d", "text": "It stopped raining, so they went inside."}, {"id": "a", "text": "They went inside because it began to rain."}]'::jsonb, 3, '{"strategy": "rain, so went inside = גשם, לכן נכנסו. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר ''went inside''", "הפוך — ''outside'' סותר ''inside''", "סותר ''began to rain''", "נכון! אותה סיבה-תוצאה בדיוק"]}', 1.5, -2.0, 0.25, 1, 'ai', NULL, true),
('e46aa318-f690-4b22-a4bf-1a51bd9b6f6a', 'restatement', 'The baby fell asleep during the car ride.', NULL, '[{"id": "d", "text": "During the car ride, the baby fell asleep."}, {"id": "c", "text": "The baby fell asleep before the car ride."}, {"id": "b", "text": "The baby stayed awake during the car ride."}, {"id": "a", "text": "The car ride began after the baby fell asleep."}]'::jsonb, 0, '{"strategy": "during the car ride = במהלך הנסיעה. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["נכון! אותה עובדה בדיוק", "''לפני'' סותר ''during''", "סותר ''fell asleep''", "הופך את סדר האירועים"]}', 1.2, -2.0, 0.25, 1, 'ai', NULL, true),
('3242f3c5-7286-40f7-a272-9f426b253c8c', 'restatement', 'My father cooks dinner every Sunday.', NULL, '[{"id": "b", "text": "My father never cooks dinner."}, {"id": "a", "text": "Every Sunday, dinner is cooked by my father."}, {"id": "c", "text": "My father cooks dinner every Monday."}, {"id": "d", "text": "My father eats dinner every Sunday."}]'::jsonb, 1, '{"strategy": "cooks = מבשל. פעיל לסביל.", "correct_reason": "אותה עובדה בדיוק, בקול סביל.", "options_analysis": ["סותר ''cooks dinner every Sunday''", "נכון! אותה עובדה בדיוק, בקול סביל", "''יום שני'' סותר ''Sunday''", "''אוכל'' שונה מ''מבשל''"]}', 1.36, -2.0, 0.25, 1, 'ai', NULL, true),
('71d85630-0bbe-4675-b09f-05555e853a3e', 'restatement', 'She likes tea more than coffee.', NULL, '[{"id": "d", "text": "She does not like tea or coffee."}, {"id": "a", "text": "She prefers coffee to tea."}, {"id": "c", "text": "She prefers tea to coffee."}, {"id": "b", "text": "She likes coffee more than tea."}]'::jsonb, 2, '{"strategy": "likes tea more than coffee = מעדיפה תה על פני קפה.", "correct_reason": "prefers = מעדיפה. אותה עדיפות בדיוק.", "options_analysis": ["סותר את שני החלקים", "הופך את סדר העדיפות", "נכון! prefers tea to coffee = אותה עדיפות בדיוק", "סותר את המקור — תה מועדף, לא קפה"]}', 1.37, -2.0, 0.25, 1, 'ai', NULL, true),
('415fffd5-c9de-4074-a3b7-b3ae84716cac', 'restatement', 'The children were excited about the school trip.', NULL, '[{"id": "d", "text": "The children did not want to go on the trip."}, {"id": "b", "text": "The school trip was cancelled."}, {"id": "c", "text": "The children were bored about the school trip."}, {"id": "a", "text": "The school trip made the children excited."}]'::jsonb, 3, '{"strategy": "excited about the trip = נרגשים מהטיול.", "correct_reason": "אותה משמעות בדיוק, ניסוח סיבתי.", "options_analysis": ["סותר ''excited'' — הם כן רצו ללכת", "לא נאמר במקור שהטיול בוטל", "הפוך — ''bored'' סותר ''excited''", "נכון! אותה משמעות בדיוק: הטיול גרם להתרגשות"]}', 1.37, -2.0, 0.25, 1, 'ai', NULL, true),
