('182d4cbb-9885-4edc-a6c3-2170184868d4', 'reading_comprehension', 'Has Anna''s brother ever caught a fish?', '4656848e-4fcb-49a5-b307-cbef8607b513', '[{"id": "c", "text": "Yes, once"}, {"id": "b", "text": "Yes, many times"}, {"id": "a", "text": "The passage does not mention fishing"}, {"id": "d", "text": "No, he has never caught one"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את המידע על אחיה של אנה.", "correct_reason": "הפסקה אומרת: ''though he has never caught one yet''.", "options_analysis": ["סותר את הפסקה — הוא לא תפס אף פעם", "סותר את הפסקה במפורש", "הפסקה כן מזכירה דיג", "נכון! נאמר במפורש בפסקה"]}', 1.32, -2.0, 0.25, 1, 'ai', NULL, true),
